rm -rf "$TSET/coordination-trigger-01"
cp -R "$TSET/orchestrator-trigger-01" "$TSET/no-such-skill-trigger-01"
sed 's/max: 0/max: 1/' "$ROOT/trigger-evals/model-routing-no-trigger-01/graders/skill-not-loaded.md" \
