check "an open-questions label worded otherwise, left as its placeholder, is a finding" "1|1" \
  "$(bash "$LINT" "$OQ_OTHER_PLACEHOLDER" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$OQ_OTHER_PLACEHOLDER" 2>&1 | grep -c "open-questions field is still its placeholder")"
check "an open-questions label worded otherwise, with a value after its colon, lints clean" "0" "$(bash "$LINT" "$OQ_OTHER_FILLED" >/dev/null 2>&1; echo $?)"
check "an open-questions value that starts on the next line, as items, lints clean" "0|0" \
  "$(bash "$LINT" "$OQ_NEXT_LINE" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$OQ_NEXT_LINE_INDENTED" >/dev/null 2>&1; echo $?)"
SUCCBIG="$WORK/succession-big.md"
{ cat "$SUCCFILL"; printf '\n'; head -c 10000 /dev/zero | tr '\0' 'x'; printf '\n'; } > "$SUCCBIG"
SUCCBIG_N=$(LC_ALL=C tr -d '\200-\277' < "$SUCCBIG" | wc -c | tr -d ' ')
check "a succession brief over 9,000 characters is a finding naming the count and the limit" "1|1|1" \
  "$(bash "$LINT" "$SUCCBIG" 2>&1 | grep -c "succession brief is $SUCCBIG_N characters, over the limit of 9000")|$(bash "$LINT" "$SUCCBIG" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$SUCCBIG" 2>&1 | grep -c ': 1 finding(s)')"
# The limit is 9,000 characters: the filled brief padded to 9,100 is refused, to 8,900 it passes.
succ_padded() {  # $1 out file, $2 the characters the lint counts
  local rest; rest=$(sed "/^- The operator's open questions/s/:.*\$/:/" "$SUCCFILL" | LC_ALL=C tr -d '\200-\277' | wc -c | tr -d ' ')
  { cat "$SUCCFILL"; head -c $(( $2 - rest - 1 )) /dev/zero | tr '\0' 'x'; printf '\n'; } > "$1"
}
SUCC9100="$WORK/succession-9100.md"; succ_padded "$SUCC9100" 9100
SUCC8900="$WORK/succession-8900.md"; succ_padded "$SUCC8900" 8900
check "a filled succession brief of 9,100 characters is refused, one of 8,900 passes" "1|1|0" \
  "$(bash "$LINT" "$SUCC9100" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$SUCC9100" 2>&1 | grep -c 'over the limit of 9000 once the open-questions value is set apart (9100)')|$(bash "$LINT" "$SUCC8900" >/dev/null 2>&1; echo $?)"
# Check 16: the rulings file sits outside the brief's cap. A 20,000-character one beside the same
# two briefs, its path the same length, changes neither verdict, and is one warning, never a refusal.
RBIG="$WORK/q/rulings.md"; mkdir -p "$WORK/q"
printf '# Standing rulings\n\n' > "$RBIG"; i=0
while [ "$(LC_ALL=C tr -d '\200-\277' < "$RBIG" | wc -c | tr -d ' ')" -lt 20000 ]; do
  i=$((i + 1)); printf -- '- 2026-11-04T10:%02d:00Z « Ruling number %d, kept word for word as he said it. » — the method (row %d)\n' $((i % 60)) "$i" "$i" >> "$RBIG"
done
sed "s#$WORK/r/rulings.md#$RBIG#" "$SUCC9100" > "$WORK/succession-9100-big.md"
sed "s#$WORK/r/rulings.md#$RBIG#" "$SUCC8900" > "$WORK/succession-8900-big.md"
check "a 20,000-character rulings file beside them changes neither verdict" "yes|1|1|0|1" \
  "$([ "$(LC_ALL=C tr -d '\200-\277' < "$RBIG" | wc -c | tr -d ' ')" -ge 20000 ] && echo yes || echo no)|$(bash "$LINT" "$WORK/succession-9100-big.md" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$WORK/succession-9100-big.md" 2>&1 | grep -c '(9100)')|$(bash "$LINT" "$WORK/succession-8900-big.md" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$WORK/succession-8900-big.md" 2>&1 | grep -c 'warning: rulings file .* characters, over 8000')"
check "the filled brief with its two-entry rulings file raises no warning" "0" \
  "$(bash "$LINT" "$SUCCFILL" 2>&1 | grep -c 'warning')"
# Check 17: a state file left unpruned is the journal a successor ends up reading (158,176 bytes
# at one handover). Past 30,000 characters it is one warning naming the pruning rule, never a
# refusal; at 29,000 nothing is said.
state_brief() {  # $1 out brief, $2 the state file's size in characters
  local f="${1%.md}-state.md"
  head -c "$2" /dev/zero | tr '\0' 'x' > "$f"
  sed "s#state file \`/tmp\`#state file \`$f\`#" "$SUCCFILL" > "$1"
}
S_BIG="$WORK/succ-state-big.md"; state_brief "$S_BIG" 30001
S_SMALL="$WORK/succ-state-small.md"; state_brief "$S_SMALL" 29000
check "a state file past 30,000 characters is one warning naming the pruning rule, not a finding" "1|0|1|1|0" \
  "$(grep -c "state file \`$WORK/succ-state-big-state.md\`" "$S_BIG")|$(bash "$LINT" "$S_BIG" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$S_BIG" 2>&1 | grep -c 'warning')|$(bash "$LINT" "$S_BIG" 2>&1 | grep -c "warning: state file $WORK/succ-state-big-state.md is 30001 characters, over 30000: prune it, lifecycle item 0")|$(bash "$LINT" "$S_SMALL" 2>&1 | grep -c 'warning')"
# Check 16 refuses a succession brief whose rulings file is missing or unnamed, and an entry of
# that file without its date or its « » quote, naming the file's line.
rulings_brief() {  # $1 out brief, $2 the rulings file's content, or ABSENT for a path to no file
  local f="${1%.md}-rulings.md"
  [ "$2" = ABSENT ] || printf '%s\n' "$2" > "$f"
  sed "s#$WORK/r/rulings.md#$f#" "$SUCCFILL" > "$1"
}
R_MISSING="$WORK/succ-r-missing.md"; rulings_brief "$R_MISSING" ABSENT
R_NODATE="$WORK/succ-r-nodate.md"
rulings_brief "$R_NODATE" $'# Standing rulings\n\n- 2026-11-04T09:10:00Z « Dated. » — x (row 1)\n- « Undated. » — y (row 2)'
R_NOQUOTE="$WORK/succ-r-noquote.md"
rulings_brief "$R_NOQUOTE" $'# Standing rulings\n\n- 2026-11-04T09:10:00Z He said to ship. — y (row 2)'
R_SHORTDATE="$WORK/succ-r-shortdate.md"
rulings_brief "$R_SHORTDATE" $'# Standing rulings\n\n- 2026-11-04 « A day, no time. » — y (row 2)'
R_UNNAMED="$WORK/succ-r-unnamed.md"; grep -v '^- Standing rulings:' "$SUCCFILL" > "$R_UNNAMED"
check "a succession brief whose rulings file is missing is refused" "1|1" \
  "$(bash "$LINT" "$R_MISSING" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_MISSING" 2>&1 | grep -c 'rulings file not found')"
check "a succession brief that names no rulings file is refused" "1|1" \
  "$(bash "$LINT" "$R_UNNAMED" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_UNNAMED" 2>&1 | grep -c 'names no rulings file')"
check "a rulings entry without its date is refused, naming its line" "1|1|0" \
  "$(bash "$LINT" "$R_NODATE" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_NODATE" 2>&1 | grep -c 'succ-r-nodate-rulings.md:4: rulings entry without its date')|$(bash "$LINT" "$R_NODATE" 2>&1 | grep -c 'succ-r-nodate-rulings.md:3:')"
check "a rulings entry dated without its time is refused" "1|1" \
  "$(bash "$LINT" "$R_SHORTDATE" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_SHORTDATE" 2>&1 | grep -c 'succ-r-shortdate-rulings.md:3: rulings entry without its date')"
check "a rulings entry without its « » quote is refused, naming its line" "1|1" \
  "$(bash "$LINT" "$R_NOQUOTE" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_NOQUOTE" 2>&1 | grep -c 'succ-r-noquote-rulings.md:3: rulings entry without his words')"
# Check 18: a succession brief carries its mode on one line, `Mode: build` or `Mode: investigate`,
# the line the launcher reads to start the successor on it; prose alone, a missing line or another
# word is refused.
M_NONE="$WORK/succ-m-none.md"; grep -v '^Mode: ' "$SUCCFILL" > "$M_NONE"
M_PROSE="$WORK/succ-m-prose.md"; sed 's/^Mode: .*/Mode: `build` (load the rulebook with it)/' "$SUCCFILL" > "$M_PROSE"
M_OTHER="$WORK/succ-m-other.md"; sed 's/^Mode: .*/Mode: both/' "$SUCCFILL" > "$M_OTHER"
M_INV="$WORK/succ-m-inv.md"; sed 's/^Mode: .*/Mode: investigate/' "$SUCCFILL" > "$M_INV"
check "a succession brief with no Mode line, a prose mode or another word is refused; build and investigate pass" "1|1|1|1|0|0" \
  "$(bash "$LINT" "$M_NONE" 2>&1 | grep -c 'succession brief carries no .Mode: build. or .Mode: investigate. line')|$(bash "$LINT" "$M_PROSE" 2>&1 | grep -c 'carries no .Mode: build. or .Mode: investigate. line')|$(bash "$LINT" "$M_OTHER" 2>&1 | grep -c 'carries no .Mode: build. or .Mode: investigate. line')|$(bash "$LINT" "$M_NONE" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$M_INV" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$SUCCFILL" >/dev/null 2>&1; echo $?)"
check "the unnamed-file message spells the path it asks for, with no stray bracket" "1|0" \
  "$(bash "$LINT" "$R_UNNAMED" 2>&1 | grep -cF 'add "- Standing rulings: `<briefs dir>/rulings.md`", the operator')|$(bash "$LINT" "$R_UNNAMED" 2>&1 | grep -cF 'rulings.md>`')"
# The successor reads the path from the project directory, not the brief's: a relative one is
# refused even with a rulings.md beside the brief, and a leading `~` is the home. A quote his
# words carry over two lines is one entry, the continuation indented under its `- `.
R_RELDIR="$WORK/r-rel"; mkdir -p "$R_RELDIR"; cp "$SUCCRULINGS" "$R_RELDIR/rulings.md"
sed "s#\`$WORK/r/rulings.md\`#\`rulings.md\`#" "$SUCCFILL" > "$R_RELDIR/brief.md"
check "a relative rulings path is refused, asking for the absolute one" "1|1|1" \
  "$(grep -c '^- Standing rulings: `rulings.md`' "$R_RELDIR/brief.md")|$(cd / && bash "$LINT" "$R_RELDIR/brief.md" >/dev/null 2>&1; echo $?)|$(cd / && bash "$LINT" "$R_RELDIR/brief.md" 2>&1 | grep -cF 'rulings path is relative: rulings.md — name it absolute, `<briefs dir>/rulings.md`')"
R_TILDEHOME="$WORK/r-home"; mkdir -p "$R_TILDEHOME/briefs"; cp "$SUCCRULINGS" "$R_TILDEHOME/briefs/rulings.md"
sed "s#\`$WORK/r/rulings.md\`#\`~/briefs/rulings.md\`#" "$SUCCFILL" > "$WORK/succ-r-tilde.md"
check "a rulings path under ~ is read in the home" "1|0|0" \
  "$(grep -c '^- Standing rulings: `~/briefs/rulings.md`' "$WORK/succ-r-tilde.md")|$(HOME="$R_TILDEHOME" bash "$LINT" "$WORK/succ-r-tilde.md" >/dev/null 2>&1; echo $?)|$(HOME="$R_TILDEHOME" bash "$LINT" "$WORK/succ-r-tilde.md" 2>&1 | grep -c 'rulings file not found')"
R_TWOLINE="$WORK/succ-r-twoline.md"
rulings_brief "$R_TWOLINE" $'# Standing rulings\n\n- 2026-11-04T09:10:00Z « Ship\n  only on Monday. » — the release day (row 1)\n- 2026-11-04T09:12:00Z « Split\n  it. »'
check "a quote over two lines is one entry, and lints clean" "0|0" \
  "$(bash "$LINT" "$R_TWOLINE" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_TWOLINE" 2>&1 | grep -c 'rulings entry')"
R_TWOLINEBAD="$WORK/succ-r-twolinebad.md"
rulings_brief "$R_TWOLINEBAD" $'# Standing rulings\n\n- 2026-11-04T09:10:00Z He said\n  to ship on Monday. — the release day (row 1)'
check "an entry over two lines with no quote is still refused, naming its first line" "1|1" \
  "$(bash "$LINT" "$R_TWOLINEBAD" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$R_TWOLINEBAD" 2>&1 | grep -c 'succ-r-twolinebad-rulings.md:3: rulings entry without his words')"
SUCCOTHER="$WORK/not-a-succession.md"
{ cat "$B/good.md"; head -c 10000 /dev/zero | tr '\0' 'x'; printf '\n'; } > "$SUCCOTHER"
check "the size limit binds a succession brief only" "0" "$(bash "$LINT" "$SUCCOTHER" >/dev/null 2>&1; echo $?)"
check "the rulings check binds a succession brief only" "0" "$(bash "$LINT" "$SUCCOTHER" 2>&1 | grep -c 'rulings')"
# A succession brief written by hand dropped the template's step 4, and the predecessor stayed
# open a day after the takeover: a brief whose reader confirms the takeover to its predecessor
# carries the launcher's close, and a brief whose reader is the one handed over from is not held.
SUCCHAND="$WORK/succession-by-hand.md"
cat > "$SUCCHAND" <<'BRIEF'
# Handover: you are Orch: scratch

You succeed the session Orch: scratch.

## Your first moves

1. Send the coordinator one line with your new name.
2. Reply to your predecessor with exactly « takeover confirmed ».
3. Then end your turn on `waiting: done`.
BRIEF
check "a succession brief without the predecessor's close is a finding naming the step and the template" "1|1|1" \
  "$(bash "$LINT" "$SUCCHAND" >/dev/null 2>&1; echo $?)|$(bash "$LINT" "$SUCCHAND" 2>&1 | grep -c "succession brief without the predecessor's close")|$(bash "$LINT" "$SUCCHAND" 2>&1 | grep -c 'instantiate the template')"
SUCCHANDCLOSE="$WORK/succession-by-hand-close.md"
{ cat "$SUCCHAND"; printf '4. On its handed over, close its tab: `iterm-agent.sh list`, then close --tty <its tty> --expect-title "Orch: scratch".\n'; } > "$SUCCHANDCLOSE"
check "the same brief with the close lints clean" "0" "$(bash "$LINT" "$SUCCHANDCLOSE" >/dev/null 2>&1; echo $?)"
SUCCHANDNOTITLE="$WORK/succession-by-hand-no-title.md"
{ cat "$SUCCHAND"; printf '4. On its handed over, close its tab: close --tty <its tty>.\n'; } > "$SUCCHANDNOTITLE"
check "a close with no expected title is still the finding" "1" "$(bash "$LINT" "$SUCCHANDNOTITLE" >/dev/null 2>&1; echo $?)"
SUCCFROM="$WORK/handed-over-from.md"
printf '# scratch: audit\n\nWait for « takeover confirmed », answer it with « handed over » as your last message.\n' > "$SUCCFROM"
check "a brief whose reader is handed over from is not held to the close" "0" "$(bash "$LINT" "$SUCCFROM" >/dev/null 2>&1; echo $?)"
check "succeed.md has the brief from the template, never by hand, and « handed over » sent with SendMessage" "yes|yes|yes" \
  "$(spells "$ROOT/commands/succeed.md" 'never a brief written by hand')|$(spells "$ROOT/commands/succeed.md" 'with `SendMessage` to the name it confirmed from')|$(spells "$ROOT/commands/succeed.md" 'a line written in your own tab reaches no one')"
check "the README's hooks table names the Stop hook" "yes" "$(spells "$ROOT/README.md" 'hook `Stop`')"
check "the eval selection says its two stop-gate cases grade the staged spawn line and do not run the hook" "2" \
  "$(grep -E '^\| 5[12] \|' "$ROOT/evals/SELECTION.md" | grep -c 'under staging; it does not run the hook')"
check "hooks.json declares the module and nothing else" "1|0|0" \
  "$("$py" -c 'import json,sys; d=json.load(open(sys.argv[1])); print(str(sum(m=="./register.ts" for m in d.get("modules",[])))+"|"+str(len(d.get("hooks",{})))+"|"+str(sum(k!="description" and k!="modules" for k in d)))' "$ROOT/hooks/hooks.json" 2>/dev/null)"
# The module's log is appended, never read and rewritten: every session shares it, and a
# read-then-write lost the lines written in between and wiped the history past the host's
# 4 MiB read limit. Forty writers at once keep all forty lines; past the cap the log moves
# to its one `.1` generation and the next line starts a fresh file.
LOGD="$WORK/module-log"
for i in $(seq 1 40); do sh "$ROOT/hooks/log-append.sh" "$LOGD/hooks-module.log" "line $i" 1000000 & done; wait
check "the module's log keeps every line forty sessions append at once" "40|40" \
  "$(wc -l < "$LOGD/hooks-module.log" | tr -d ' ')|$(sort -u "$LOGD/hooks-module.log" | grep -c '^line [0-9]*$')"
sh "$ROOT/hooks/log-append.sh" "$LOGD/hooks-module.log" "past the cap" 100
check "a log past its cap is rotated to one .1 generation, the new line alone in the fresh file" "40|past the cap|no" \
  "$(grep -c '^line' "$LOGD/hooks-module.log.1")|$(cat "$LOGD/hooks-module.log")|$([ -e "$LOGD/hooks-module.log.lock" ] && echo yes || echo no)"

echo "== the app, stubbed =="
# A pane behind a maximized sibling is in the tab's all_sessions and not in its sessions.
# The stub is the smallest app that tells the two apart; the live round reads the real one.
STUB='
import asyncio, sys
sys.path.insert(0, sys.argv[1])
import iterm_agent as ia
class S:
    def __init__(s, sid, tty, name): s.session_id=sid; s.tty=tty; s.name=name; s.closed=False
    async def async_get_variable(s, k): return {"tty": s.tty, "autoName": s.name}.get(k)
    async def async_close(s, force=False): s.closed=True
class T:
    def __init__(s, tid, visible, hidden): s.tab_id=tid; s.sessions=visible; s.all_sessions=visible+hidden
    async def async_close(s, force=False): raise AssertionError("tab closed")
class W:
    def __init__(s, tabs): s.window_id="w"; s.tabs=tabs
class App:
    def __init__(s, wins): s.windows=wins
a=S("A","/dev/ttys801","visible one"); b=S("B","/dev/ttys802","hidden one")
app=App([W([T("1",[a],[b])])])
'
py=$(command -v python3 || echo python3)
check "a hidden pane is found by its tty" "B" \
  "$("$py" -c "$STUB
_,_,s=asyncio.run(ia.find_tab(app,'/dev/ttys802')); print(s.session_id)" "$ROOT/skills/iterm-agents/scripts")"
check "the listing marks a hidden pane" "w1/t1 | /dev/ttys802 | hidden one | (host default) | hidden" \
  "$("$py" -c "$STUB
print([r for r in asyncio.run(ia.list_rows(app)) if 'ttys802' in r][0])" "$ROOT/skills/iterm-agents/scripts")"
# ...and the caller's own row, and no other, so an orchestrator reads which tab is its own
# before it anchors, moves or closes anything (§38). The name beside the title is the one
# the host process was launched with; the stub's other pane was launched with none.
printf '/dev/ttys801 /opt/x/host --name Orch: f --permission-mode auto\n' > "$WORK/ps-stub.txt"
check "the listing marks the caller's own row, names it, and marks no other" \
  "w1/t1 | /dev/ttys801 | visible one | Orch: f | self|0" \
  "$(ORCHESTRATOR_SELF_TTY=/dev/ttys801 ORCHESTRATOR_PS_TABLE="$WORK/ps-stub.txt" "$py" -c "$STUB
rows=asyncio.run(ia.list_rows(app))
print('%s|%d' % ([r for r in rows if 'ttys801' in r][0], len([r for r in rows if 'ttys802' in r and '| self' in r])))" "$ROOT/skills/iterm-agents/scripts")"
# The caller is not always IN the app. A session running in another terminal — a multiplexer,
# a plain shell, a remote one — still has a tty, `self_tty` still resolves it, and the app has
# no session on it. The chain is the app's and cannot be kept for a caller the app does not
# know; that is a fact to state, not a reason to fail. Observed: a spawn from such a session
# died on `AttributeError: 'NoneType' object has no attribute 'session_id'`, a traceback where
# the answer was « your tab is not one of mine, so I kept no chain » (§49).
check "a caller the app does not know has no session id, and does not raise" "" \
  "$("$py" -c "$STUB
print(asyncio.run(ia.own_session_id(app, '/dev/ttys999')))" "$ROOT/skills/iterm-agents/scripts")"
check "a caller with no tty at all is the same answer" "" \
  "$("$py" -c "$STUB
print(asyncio.run(ia.own_session_id(app, '')))" "$ROOT/skills/iterm-agents/scripts")"
check "a caller the app does know hands back its session id" "A" \
  "$("$py" -c "$STUB
print(asyncio.run(ia.own_session_id(app, '/dev/ttys801')))" "$ROOT/skills/iterm-agents/scripts")"
check "close closes the session and leaves the tab" "hidden one|True" \
  "$("$py" -c "$STUB
t=asyncio.run(ia.close_session(app,'/dev/ttys802','hidden')); print('%s|%s' % (t, b.closed))" "$ROOT/skills/iterm-agents/scripts")"

# `move`'s guard, live, is the §26 reading: a tty is recycled minutes after a close and
# the chain file named after it outlives its occupant, so an entry whose tty now belongs
owned() { ORCHESTRATOR_STATE_DIR="$ISTATE" "$py" -c "$MSTUB
print(asyncio.run(ia.move_is_owned(app, sys.argv[2], sys.argv[3])))" "$ROOT/skills/iterm-agents/scripts" "$1" "$2"; }
mkdir -p "$ISTATE/chains"
printf '{"tab_id":"2","tty":"/dev/ttys802","owner":"S-LIVE"}\n' > "$ISTATE/chains/ttys801.jsonl"
check "a tab the caller's session launched is its own to move" "True" "$(owned /dev/ttys802 /dev/ttys801)"
check "and so is its own tab" "True" "$(owned /dev/ttys801 /dev/ttys801)"
# The entry names the right tty and the WRONG tab: a recycled tty with a stranger on it.
printf '{"tab_id":"9","tty":"/dev/ttys802","owner":"S-LIVE"}\n' > "$ISTATE/chains/ttys801.jsonl"
check "a recycled tty in the chain does not make a stranger's tab movable" "False" "$(owned /dev/ttys802 /dev/ttys801)"
# The entry names the right tab and another session: a chain file that outlived its owner.
printf '{"tab_id":"2","tty":"/dev/ttys802","owner":"S-GONE"}\n' > "$ISTATE/chains/ttys801.jsonl"
check "an entry another session wrote is not the caller's to move" "False" "$(owned /dev/ttys802 /dev/ttys801)"

fi

if shard_has 3; then
echo "== iterm-agents: iTerm2 answers, or it is said why (§46) =="
# Every reading here is about the fault that made the launcher unkillable: the app stopped
# dispatching AppleEvents, the library asked it for a cookie through an UNBOUNDED
# `osascript`, and the call never returned. The suite stands both halves up with stubs, so
# none of it needs a window server.
IBIN="$WORK/ibin"
mkdir -p "$IBIN"
# An `osascript` that never answers, the way the app behaves when its main thread is wedged.
printf '#!/bin/bash\ncat >/dev/null\nsleep 60\n' > "$IBIN/osascript-deaf"
# One that answers the way a healthy app does.
printf '#!/bin/bash\ncat >/dev/null\necho 3.7.0\n' > "$IBIN/osascript-live"
# One that fails the way a missing app does.
printf '#!/bin/bash\ncat >/dev/null\necho "execution error: iTerm2 got an error" >&2\nexit 1\n' > "$IBIN/osascript-broken"
chmod +x "$IBIN"/osascript-*

ipy() { "$py" -c "
import sys
sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia
$1
"; }

check "a bounded osascript that never answers is killed and reported as a timeout" "timeout" \
  "$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-deaf" ORCHESTRATOR_PROBE_TIMEOUT=2 \
     ipy "print(ia.osascript_run('x')[0])")"
# Scoped to this suite's own stub path, not the bare name: a bare `pgrep -f osascript-deaf`
# reads machine-wide and flakes when another suite's own deaf stub is alive at the same time.
# The bracket keeps the pattern from matching the probe's own command line, which spells it.
check "the deaf probe leaves no osascript behind" "0" \
  "$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-deaf" ORCHESTRATOR_PROBE_TIMEOUT=2 \
     ipy "
import subprocess
ia.osascript_run('x')
print(subprocess.run(['pgrep','-f','$IBIN/[o]sascript-deaf'],capture_output=True,text=True).stdout.count('\n'))")"

# Proof the scoped guard still falls on a real leak: a copy of the stub started directly
# under this suite's own work directory and left running on purpose, so "0" above means a
# clean kill, not a pattern too narrow to ever match anything.
LEAKED="$IBIN/osascript-deaf-leak"
cp "$IBIN/osascript-deaf" "$LEAKED"
"$LEAKED" </dev/null >/dev/null 2>&1 &
LEAK_PID=$!
check "the scoped guard still catches a leak planted in a scratch copy" "1" \
  "$(pgrep -f -- "$LEAKED" | wc -l | tr -d ' ')"
kill "$LEAK_PID" 2>/dev/null
wait "$LEAK_PID" 2>/dev/null
rm -f "$LEAKED"
check "a live app answers the preflight with its version" "True 3.7.0" \
  "$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-live" ipy \
     "print('%s %s' % ia.app_responsive())")"
check "a wedged app fails the preflight as a timeout, not as an error" "False timeout" \
  "$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-deaf" ORCHESTRATOR_PROBE_TIMEOUT=2 ipy \
     "print('%s %s' % ia.app_responsive())")"
check "a refusing app fails the preflight as an error" "False error" \
  "$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-broken" ipy \
     "print('%s %s' % ia.app_responsive())")"

# The sample is the only reading that tells « busy » from « wedged in a modal loop », and the
# modal loop is the one an operator clears with one keystroke. The stack below is the real
# one, trimmed: a context menu left open by a single right-click.
check "a modal menu in the sample is named as the cause, with its remedy" "modal|Escape" \
  "$(ipy "
c = ia.cause_from_sample('''
 1931 -[NSView _showMenuForEvent:]  (in AppKit)
 1931 -[NSMenuTrackingSession startRunningMenuEventLoop:]  (in AppKit)
''')
print('%s|%s' % ('modal' if 'MODAL' in c else 'no', 'Escape' if 'Escape' in c else 'no'))")"
check "a sheet is named the same way" "modal" \
  "$(ipy "print('modal' if 'MODAL' in ia.cause_from_sample('1 -[NSApplication runModalForWindow:]') else 'no')")"
check "an unrecognised stack is not called a modal loop" "other" \
  "$(ipy "print('modal' if 'MODAL' in ia.cause_from_sample('1 mach_msg_trap (in libsystem_kernel.dylib)') else 'other')")"
check "no sample at all says so instead of guessing" "sampled" \
  "$(ipy "print('sampled' if 'sampled' in ia.cause_from_sample('') else 'no')")"

echo "== iterm-agents: the AppleScript rung leaves the operator where they work =="
# The API rung creates a tab without selecting it; `create tab` in AppleScript selects it,
# so an orchestrator that fell to this rung pulled the operator onto every agent it
# launched. The stub records the script the spawn sends and answers with the new tty.
AS_SENT="$WORK/as-spawn-sent.applescript"
printf '#!/bin/bash\ncat > "%s"\necho /dev/ttys900\n' "$AS_SENT" > "$IBIN/osascript-record"
chmod +x "$IBIN/osascript-record"
check "the AppleScript spawn still returns the new session's tty" "/dev/ttys900" \
  "$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-record" ipy "print(ia.as_spawn('true'))")"
check "the AppleScript spawn re-selects the operator's tab after creating the agent's" "reselects" \
  "$("$py" -c "
import sys
s = open(sys.argv[1]).read()
create = s.find('create tab')
remember = s.find('set prev to current tab')
print('reselects' if -1 < remember < create < s.find('select prev', create) else 'no')" "$AS_SENT")"
check "the re-selection is guarded, so a tab closed meanwhile cannot fail the spawn" "guarded" \
  "$("$py" -c "
import sys
s = open(sys.argv[1]).read()
select = s.find('select prev', s.find('create tab'))
opened = s.rfind('try', 0, select)
closed = s.find('end try', select)
ret = s.find('return newTty', select)
print('guarded' if -1 < opened < select < closed < ret else 'no')" "$AS_SENT")"

echo "== iterm-agents: the AppleScript close compares the title before it closes =="
# The rung used to send `close s` and read the name afterwards, so a refused title had
# already closed the tab. The stub appends every script it is sent and answers with a title.
AS_CLOSE_LOG="$WORK/as-close-sent.applescript"
printf '#!/bin/bash\ncat >> "%s"\necho "Agent: other"\n' "$AS_CLOSE_LOG" > "$IBIN/osascript-title"
chmod +x "$IBIN/osascript-title"
: > "$AS_CLOSE_LOG"
res=$(ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-title" ipy "ia.as_close('/dev/ttys901', 'Agent: fake')" 2>&1)
check "a close whose title differs is refused" "1" "$(printf '%s' "$res" | grep -c 'close: refused')"
check "and no script that closes a session was sent" "0" "$(grep -c 'close s' "$AS_CLOSE_LOG")"
: > "$AS_CLOSE_LOG"
ORCHESTRATOR_OSASCRIPT="$IBIN/osascript-title" ipy "ia.as_close('/dev/ttys901', 'Agent: other')" >/dev/null 2>&1
check "a close whose title matches is sent" "1" "$(grep -c 'close s' "$AS_CLOSE_LOG")"

echo "== iterm-agents: a self-anchor the app cannot resolve is lost, not fatal (§51) =="
# Two refusals that look alike and are not. A NAMED anchor the app does not know is a tab
# the caller got wrong: refuse it. The caller's OWN tty, when the app has no session on it,
# means the caller is running in another terminal — « beside itself » has no meaning there,
# and refusing it blocks the one spawn that exists to bring that session back into the app.
# Measured: a session outside the app could not spawn its own successor at all, which is the
# succession the operator ordered precisely to end that state.
anchored() { "$py" -c "
import sys; sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia
print('[%s]' % ia.anchor_after_probe($1, sys.argv[1], sys.argv[2]))" "$2" "$3" 2>/dev/null; }

check "an anchor the app knows is kept" "[/dev/ttys802]" \
  "$(anchored True /dev/ttys802 /dev/ttys801)"
check "the caller's own tty, unknown to the app, is dropped" "[]" \
  "$(anchored False /dev/ttys006 /dev/ttys006)"
check "and the drop is said, naming the tty" "said" \
  "$("$py" -c "
import sys; sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia
ia.anchor_after_probe(False, '/dev/ttys006', '/dev/ttys006')" 2>&1 | grep -c ttys006 | sed 's/^1$/said/')"
check_status "a NAMED anchor the app does not know is still a refusal" 1 \
  "$py" -c "
import sys; sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia
ia.anchor_after_probe(False, '/dev/ttys802', '/dev/ttys801')"

echo "== iterm-agents: the fallback ladder (§46, §48) =="
# AppleScript is the fallback and the ONLY one: it drove this plugin before the API existed.
# A third rung in another terminal was built, in tmux, and struck out by the operator — a
# session that is neither a window of its orchestrator's home session nor a tab in the window
# he reads is not an agent he can see, place or close. When BOTH rungs are down the app is
# wedged, which has a one-keystroke remedy, so the launcher names it and STOPS. Stopping
# loudly on a fault with a known remedy is the repair; routing around it into a terminal he
# never asked for is not. The windows of a home session are a placement, chosen by where the
# caller runs, not a rung a failed iTerm2 call falls to: so tmux stays refused as a backend.
check "the ladder is the api, then applescript, and nothing else" "api applescript" \
  "$(ipy "print(' '.join(ia.backend_chain()))")"
check "no terminal outside the app is offered as a rung" "api applescript" \
  "$(ipy "print(' '.join(ia.BACKENDS))")"
check "a named backend is the only rung tried" "applescript" \
  "$(ORCHESTRATOR_BACKEND=applescript ipy "print(' '.join(ia.backend_chain()))")"
check "the api can be named alone, for a caller that wants the failure" "api" \
  "$(ORCHESTRATOR_BACKEND=api ipy "print(' '.join(ia.backend_chain()))")"
check_status "an unknown backend is refused, not silently ignored" 1 \
  env ORCHESTRATOR_BACKEND=carrier-pigeon "$py" -c "
import sys; sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia; ia.backend_chain()"
check_status "and the rung that was struck out is refused by name" 1 \
  env ORCHESTRATOR_BACKEND=tmux "$py" -c "
import sys; sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia; ia.backend_chain()"
echo "== iterm-agents: a close is proved on the process table (§46) =="
# `close` printed « closed 1 session » on a session whose process was still running, and the
# operator read that line as a fact. The API's acknowledgement is that the request was taken,
# not that the session is gone; only the process table answers that.
printf '/dev/ttys901 /opt/x/claude --name Agent: survivor\n' > "$WORK/ps-alive.txt"
: > "$WORK/ps-empty.txt"
check "a session still in the process table is not reported closed" "still there" \
  "$(ORCHESTRATOR_PS_TABLE="$WORK/ps-alive.txt" ipy \
     "print('gone' if ia.wait_gone('/dev/ttys901', 1) is None else 'still there')")"
check "a session gone from the process table is reported closed" "gone" \
  "$(ORCHESTRATOR_PS_TABLE="$WORK/ps-empty.txt" ipy \
     "print('gone' if ia.wait_gone('/dev/ttys901', 1) is None else 'still there')")"
# The proof is about the host CLI and about nothing else. A tab holding only a shell has
# none to watch, the wait returns at once, and the close then rests on the app's word — true
# of the close and no evidence at all about an agent. Which of the two it was, is said.
check "a close with no agent to watch says its proof is the app's word" "said" \
  "$(ipy "print('said' if 'app' in ia.close_note('/dev/ttys901', None) else 'silent')")"
check "a close that watched an agent leave adds nothing" "" \
  "$(ipy "print(ia.close_note('/dev/ttys901', '4242'))")"
check "and what survived is named, so the operator reads which process held on" "claude" \
  "$(ORCHESTRATOR_PS_TABLE="$WORK/ps-alive.txt" ipy \
     "print('claude' if 'claude' in (ia.wait_gone('/dev/ttys901', 1) or '') else 'unnamed')")"
# Which row IS the host. Matched on the full HOST_CLI path, a host typed as a bare command
# was « not running » whenever HOST_CLI was absolute, and a wrapper that `exec`s the binary
# made every spawn die « never started » after its tab existed. A row is the host when the
# host registered its pid, or when its program's basename is HOST_CLI's or that of what
# HOST_CLI resolves to.
printf '/dev/ttys901 claude --resume x\n' > "$WORK/ps-bare.txt"
printf '/dev/ttys901 /opt/homebrew/bin/claude --name Agent: x\n' > "$WORK/ps-binary.txt"
printf '/dev/ttys901 4242 node /opt/lib/cli.js --resume x\n' > "$WORK/ps-node.txt"
printf '/dev/ttys901 -zsh\n' > "$WORK/ps-shell.txt"
mkdir -p "$WORK/wrapbin" "$WORK/hostcfg/sessions"
printf '#!/bin/bash\nexec /opt/homebrew/bin/claude "$@"\n' > "$WORK/wrapbin/claude"
printf '#!/bin/bash\nexec /opt/homebrew/bin/claude "$@"\n' > "$WORK/wrapbin/run-host.sh"
chmod +x "$WORK/wrapbin/claude" "$WORK/wrapbin/run-host.sh"
ln -sf "$WORK/wrapbin/claude" "$WORK/wrapbin/host-link"
hostp() { ORCHESTRATOR_HOST_CLI="$1" ORCHESTRATOR_PS_TABLE="$2" CLAUDE_CONFIG_DIR="$WORK/hostcfg" \
  ipy "print('host' if ia.host_cli_on('/dev/ttys901') else 'none')"; }
check "an absolute HOST_CLI matches a bare host row" "host" "$(hostp /opt/homebrew/bin/claude "$WORK/ps-bare.txt")"
check "a wrapper path matches the binary's row" "host" "$(hostp "$WORK/wrapbin/claude" "$WORK/ps-binary.txt")"
check "a link to the wrapper matches through what it resolves to" "host" "$(hostp "$WORK/wrapbin/host-link" "$WORK/ps-binary.txt")"
check "a wrapper named otherwise does not match on argv alone" "none" "$(hostp "$WORK/wrapbin/run-host.sh" "$WORK/ps-node.txt")"
printf '{"pid":4242,"sessionId":"s-reg","name":"Agent: x"}\n' > "$WORK/hostcfg/sessions/4242.json"
check "a pid the host registered is the host, whatever its argv" "host" "$(hostp "$WORK/wrapbin/run-host.sh" "$WORK/ps-node.txt")"
check "a shell on the tty is not the host" "none" "$(hostp /opt/homebrew/bin/claude "$WORK/ps-shell.txt")"
check "verify reads a bare host row under an absolute HOST_CLI" "0" \
  "$(ORCHESTRATOR_HOST_CLI=/opt/homebrew/bin/claude ORCHESTRATOR_PS_TABLE="$WORK/ps-bare.txt" bash "$AGENT" verify --tty /dev/ttys901 >/dev/null 2>&1; echo $?)"
vpid() { ORCHESTRATOR_HOST_CLI=a-host ORCHESTRATOR_PS_TABLE="$WORK/ps-two.txt" CLAUDE_CONFIG_DIR="$WORK/hostcfg" \
  bash "$AGENT" verify --tty /dev/ttys901 "$@"; }
vpid_status() { vpid "$@" >/dev/null 2>&1; echo "exit $?"; }
check "verify --pid answers for the first host CLI on the tty" "a-host running on /dev/ttys901 (pid 5100)|exit 0" \
  "$(vpid --pid 5100 2>&1)|$(vpid_status --pid 5100)"
check "verify --pid answers for a host CLI that is not the first" "a-host running on /dev/ttys901 (pid 5101)|exit 0" \
  "$(vpid --pid 5101 2>&1)|$(vpid_status --pid 5101)"
check "verify --pid of a pid the tty does not run is not running, and silent" "|exit 1" \
  "$(vpid --pid 9999 2>&1)|$(vpid_status --pid 9999)"
check "verify without --pid names the first host CLI" "a-host running on /dev/ttys901 (pid 5100)" "$(vpid 2>&1)"
check "a --pid that is no number is a usage error, not « not running »" "exit 2|1" \
  "$(vpid_status --pid abc)|$(vpid --pid abc 2>&1 >/dev/null | grep -c 'invalid int value')"
# A home session's tab carries only the tmux client; the host runs in window 0 of the server.
mkdir -p "$WORK/vhome"
printf '#!/bin/sh\nfor a in "$@"; do [ "$a" = list-panes ] && printf "0 /dev/ttys971\\n1 /dev/ttys972\\n"; done\nexit 0\n' > "$WORK/vhome/tmux"
chmod +x "$WORK/vhome/tmux"
printf '/dev/ttys970 6000 %s -u -L orch-vhome attach -t home\n/dev/ttys971 6001 a-host --name Orch\n/dev/ttys972 6002 a-host --name Agent\n' \
  "$WORK/vhome/tmux" > "$WORK/vhome/ps.txt"
printf '/dev/ttys970 6000 %s -u -L orch-vhome attach -t home\n/dev/ttys971 6003 -zsh\n' \
  "$WORK/vhome/tmux" > "$WORK/vhome/ps-dead.txt"
vhome() { ORCHESTRATOR_TMUX="$WORK/vhome/tmux" ORCHESTRATOR_HOST_CLI=a-host ORCHESTRATOR_PS_TABLE="$1" \
  CLAUDE_CONFIG_DIR="$WORK/hostcfg" bash "$AGENT" verify --tty /dev/ttys970 "${@:2}"; }
check "verify of a home tab reads the host in window 0 of its server" "a-host running on /dev/ttys970 (pid 6001)|0" \
  "$(vhome "$WORK/vhome/ps.txt" 2>&1)|$(vhome "$WORK/vhome/ps.txt" >/dev/null 2>&1; echo $?)"
check "verify of a home tab whose window 0 runs no host is not running" "1" \
  "$(vhome "$WORK/vhome/ps-dead.txt" >/dev/null 2>&1; echo $?)"
# A host on the tab's own tty is not the home's host: only window 0 of the server is read.
printf '/dev/ttys970 6000 %s -u -L orch-vhome attach -t home\n/dev/ttys970 6004 a-host --name Stray\n/dev/ttys971 6003 -zsh\n' \
  "$WORK/vhome/tmux" > "$WORK/vhome/ps-tab-host.txt"
check "verify of a home tab ignores a host on the tab's tty when window 0 runs none" "1" \
  "$(vhome "$WORK/vhome/ps-tab-host.txt" >/dev/null 2>&1; echo $?)"
check "the close note claims no more than the table showed" "1|0" \
  "$(ipy "print(ia.close_note('/dev/ttys901', None))" | grep -c 'no process matching claude was found on /dev/ttys901')|$(ipy "print(ia.close_note('/dev/ttys901', None))" | grep -c 'was running')"

echo "== iterm-agents: a close ends the host it closes =="
# The app accepted a close, the tab went, and the host kept running: the terminal's
# session-keeping daemon held the tty open, no hangup ever reached the host, and the host
# ignored the SIGTERM sent by hand. The launcher no longer leaves the end to the app: the pid
# and start time read BEFORE the close are waited for, then sent SIGTERM, then SIGKILL, each
# step logged, and the close is reported only once the process table shows that process gone.
# The fake hosts are real processes of the suite's own, entered in the stand-in table on a
# tty no session holds; the proof is read on the real process table, by pid.
ESTATE="$WORK/end-state"
# The host CLI is named a-host here, its stand-in rows matched on that name.
host_cli_kept=$ORCHESTRATOR_HOST_CLI
export ORCHESTRATOR_HOST_CLI=a-host
mkdir -p "$ESTATE" "$WORK/end-cfg/sessions"
# One that ignores SIGTERM, the way the stuck host did; one that dies of it.
stubborn() { "$py" -c 'import signal, time
signal.signal(signal.SIGTERM, signal.SIG_IGN)
time.sleep(120)' >/dev/null 2>&1 & echo $!; }
polite() { "$py" -c 'import time; time.sleep(120)' >/dev/null 2>&1 & echo $!; }
# A killed process its parent has not reaped is a zombie, and a container without an init that
# reaps leaves it one: kill -0 still finds it, so the state ps reads decides.
alive() { case "$(ps -o stat= -p "$1" 2>/dev/null | tr -d ' ')" in ''|Z*) echo gone ;; *) echo alive ;; esac; }
# A close of the tab on $1 whose host is pid $2, asked with --expect-title $3 of a session
# titled $4, through a terminal of the probe's own that accepts the close and ends nothing.
endclose() {
  printf '/dev/%s %s /opt/x/a-host --name Agent: fake\n' "$1" "$2" > "$WORK/ps-end.txt"
  ORCHESTRATOR_PS_TABLE="$WORK/ps-end.txt" ORCHESTRATOR_STATE_DIR="$ESTATE" \
  ORCHESTRATOR_CLOSE_TIMEOUT=1 ORCHESTRATOR_TERM_GRACE=1 ORCHESTRATOR_KILL_GRACE=3 \
  CLAUDE_CONFIG_DIR="$WORK/end-cfg" ipy "
class Accepting:
    def close(self, tty, expect):
        if expect and ia.stable_title(expect) not in ia.stable_title('$4'):
            ia.die('close: refused: session on %s is titled $4' % tty)
        return ''
    def survives(self, closed_id): return False
ia.terminal_for = lambda tty: Accepting()
ia.close_tab('/dev/$1', '$3')
print('proved gone')" 2>&1
}
: > "$ESTATE/close.log"
sp=$(stubborn)
out=$(endclose ttys961 "$sp" "Agent: fake" "Agent: fake")
check "a host that ignores SIGTERM is sent SIGKILL, and the close is proved on its pid" "1|1|1|gone" \
  "$(printf '%s' "$out" | grep -c "SIGTERM sent to $sp")|$(printf '%s' "$out" | grep -c "SIGKILL sent to $sp")|$(printf '%s' "$out" | grep -c '^proved gone$')|$(alive "$sp")"
check "each step of the escalation is logged in the state directory" "1|1|1" \
  "$(grep -c "still running on /dev/ttys961 after 1s" "$ESTATE/close.log")|$(grep -c "SIGTERM sent to $sp" "$ESTATE/close.log")|$(grep -c "SIGKILL sent to $sp" "$ESTATE/close.log")"
pp=$(polite)
out=$(endclose ttys962 "$pp" "Agent: fake" "Agent: fake")
check "a host that dies of SIGTERM is never sent SIGKILL" "1|0|1|gone" \
  "$(printf '%s' "$out" | grep -c "SIGTERM sent to $pp")|$(printf '%s' "$out" | grep -c 'SIGKILL')|$(printf '%s' "$out" | grep -c '^proved gone$')|$(alive "$pp")"
# The title guard is first: a session whose title was not checked is sent nothing.
sg=$(stubborn)
out=$(endclose ttys963 "$sg" "Agent: other" "Agent: fake")
check "a close refused by its title signals nothing" "1|0|alive" \
  "$(printf '%s' "$out" | grep -c 'close: refused')|$(printf '%s' "$out" | grep -c 'SIG')|$(alive "$sg")"
# A pid is a number the system hands out again: the start time read before the close is
# what names the process, and a pid now started at another time is another process.
check "a pid now held by a process started at another time is not signalled" "True|alive" \
  "$(ORCHESTRATOR_STATE_DIR="$ESTATE" ORCHESTRATOR_CLOSE_TIMEOUT=1 ipy "print(ia.end_host('$sg', 'Thu Jan  1 00:00:00 1970', '/dev/ttys963', 'close'))" 2>&1)|$(alive "$sg")"
check "the identity read before a close is the pid and the start time of the table" "$sg|yes" \
  "$(printf '/dev/ttys963 %s /opt/x/a-host\n' "$sg" > "$WORK/ps-end.txt"; ORCHESTRATOR_PS_TABLE="$WORK/ps-end.txt" CLAUDE_CONFIG_DIR="$WORK/end-cfg" ipy "
pid, start = ia.host_identity('/dev/ttys963')
print('%s|%s' % (pid, 'yes' if start == ia.process_state(pid)[0] and start else 'no'))")"
kill -9 "$sg" 2>/dev/null
# « Gone » is read on the pid with its start time, never on the tty: a host killed under the
# terminal's daemon stays in the table for days, its tty released (`??`), in the exiting
# state `?Es` its parent never reaps, and a zombie is the same end. Both have exited and run
# nothing more: they are gone. A live state, the same start, is not.
check "an exited process its parent has not reaped is gone, a live one is not" "True|True|False|True" \
  "$(ipy "
ia.process_state = lambda pid: ('S0', '?Es')
a = ia.process_gone('7', 'S0')
ia.process_state = lambda pid: ('S0', 'Z+')
b = ia.process_gone('7', 'S0')
ia.process_state = lambda pid: ('S0', 'Ss+')
c = ia.process_gone('7', 'S0')
ia.process_state = lambda pid: None
print('%s|%s|%s|%s' % (a, b, c, ia.process_gone('7', 'S0')))")"
# The exiting mark is read among all the flags, not only first: `UE`, `SE`, `?Es`; a zombie
# `Z+` is gone; `Ss+` and `S+` are live.
check "the exiting flag is read anywhere after the state letter" "True|True|True|True|False|False" \
  "$(ipy "
r = []
for stat in ('UE', 'SE', '?Es', 'Z+', 'Ss+', 'S+'):
    ia.process_state = lambda pid, stat=stat: ('S0', stat)
    r.append(str(ia.process_gone('7', 'S0')))
print('|'.join(r))")"
# The close's proof reads the tty and the host on it, and an exiting `?Es` host passes it: the
# tab went, the close was reported, and the pane drew the session live for hours on the pid
# the hooks module's store recorded. The close now names that pid on stderr while the table
# lists it, with its state, and its exit is the same. The table is the probe's own: nothing is
# signalled, and a row of another tty or a pid gone is named nowhere.
LSTATE="$WORK/linger-state"; LMOD="$WORK/linger-module"
mkdir -p "$LSTATE" "$LMOD/store/sessions"
printf '%s\n' '{"role":"orchestrator","name":"Orch: ghost","pid":"56717","tty":"/dev/ttys964","updated_at":"2026-01-01T00:00:00Z"}' > "$LMOD/store/sessions/ghost"
printf '%s\n' '{"role":"agent","name":"Agent: other","pid":"56800","tty":"/dev/ttys965","updated_at":"2026-01-01T00:00:00Z"}' > "$LMOD/store/sessions/other"
printf '/dev/ttys964 56717 /opt/x/a-host --name Orch: ghost\n' > "$WORK/ps-linger.txt"
lingerclose() {
  env -u ORCHESTRATOR_DRY_RUN ORCHESTRATOR_PS_TABLE="$WORK/ps-linger.txt" ORCHESTRATOR_STATE_DIR="$LSTATE" \
  ORCHESTRATOR_MODULE_DIR="$LMOD" ORCHESTRATOR_CLOSE_TIMEOUT=1 CLAUDE_CONFIG_DIR="$WORK/end-cfg" "$py" -c "
import sys
sys.path.insert(0, '$ROOT/skills/iterm-agents/scripts')
import iterm_agent as ia
class Accepting:
    def close(self, tty, expect): return ''
    def survives(self, closed_id): return False
ia.terminal_for = lambda tty: Accepting()
ia.os.kill = lambda pid, sig: (_ for _ in ()).throw(AssertionError('signalled %s' % pid))
ia.process_state = lambda pid: $1
try:
    ia.cmd_close(['--tty', '/dev/ttys964', '--expect-title', 'Orch: ghost', '--keep-checkout'])
except SystemExit as exc:
    print('exit %s' % exc.code)
else:
    print('exit 0')"
}
out=$(lingerclose "{'56717': ('S0', '?Es'), '56800': ('S0', 'Ss+')}.get(pid)" 2>&1)
check "a close whose recorded host lingers exiting names its pid and state, and exits as before" "1|1|0|1|1" \
  "$(printf '%s' "$out" | grep -c '^closed 1 session on /dev/ttys964$')|$(printf '%s' "$out" | grep -c '^close: pid 56717 lingers (?Es)$')|$(printf '%s' "$out" | grep -c '56800')|$(printf '%s' "$out" | grep -c '^exit 0$')|$(grep -c 'close: pid 56717 lingers (?Es)' "$LSTATE/close.log")"
: > "$WORK/ps-linger.txt"
out=$(lingerclose "None" 2>&1)
check "a close whose recorded host is gone from the table names no pid" "1|0|1" \
  "$(printf '%s' "$out" | grep -c '^closed 1 session on /dev/ttys964$')|$(printf '%s' "$out" | grep -c 'lingers')|$(printf '%s' "$out" | grep -c '^exit 0$')"
check "the pids a close names are the store's rows on its tty, an unreadable row skipped" "56717" \
  "$(printf 'not json' > "$LMOD/store/sessions/torn"; ORCHESTRATOR_MODULE_DIR="$LMOD" ipy "print(','.join(ia.recorded_pids({'/dev/ttys964'})))")"
# A row write in flight is a temporary file beside the rows (the module's writeAtomic, the
# launcher's row_write): never a row whose pid a close names.
check "a temporary file beside the store's rows names no pid to a close" "56717" \
  "$(printf '%s\n' '{"role":"agent","name":"Agent: late","pid":"56999","tty":"/dev/ttys964","updated_at":"2026-01-01T00:00:00Z"}' > "$LMOD/store/sessions/late.tmp-1-abcdef"; ORCHESTRATOR_MODULE_DIR="$LMOD" ipy "print(','.join(ia.recorded_pids({'/dev/ttys964'})))")"
rm -f "$LMOD/store/sessions/late.tmp-1-abcdef"

# The store's row, written by the launcher as the hooks module writes it: the same key, the
# same compact JSON line, the same temporary file renamed into place. tests/row-rule.ts runs
# the module's own writer (writeSession) under node; each case writes one patch through both,
# into two module directories, and the two files are compared byte for byte. The patches
# spell their non-ASCII characters as JSON escapes, the odd id as printf octal escapes.
RTS="$WORK/row-ts"; RPY="$WORK/row-py"
rowts() { ORCHESTRATOR_MODULE_DIR="$RTS" node --no-warnings "$ROOT/tests/row-rule.ts" "$@" 2>&1; }
rowpy() {  # <id> <patch JSON>: row_write's answer, then the temporary file it renamed
  ROW_ID="$1" ROW_PATCH="$2" ORCHESTRATOR_MODULE_DIR="$RPY" ORCHESTRATOR_PS_TABLE="$WORK/ps-row-none.txt" ipy '
import json, os
moved = []
rename = os.replace
def spy(src, dst):
    moved.append(src)
    rename(src, dst)
os.replace = spy
print(ia.row_write(os.environ["ROW_ID"], json.loads(os.environ["ROW_PATCH"]), "birth"))
print("\n".join(moved))' 2>&1
}
# The pid the merge case finds in its row runs nowhere: the stand-in lists another one.
printf 'ttys002 5151 sh\n' > "$WORK/ps-row-none.txt"
tmpshape() { case "${1#"$2".tmp-}" in "$1") echo "no temp" ;; *) printf '%s' "${1#"$2".tmp-}" | grep -qE '^[0-9]{13}-[0-9a-z]{1,6}$' && echo ok || echo "bad: $1" ;; esac; }
GPATCH='{"role":"agent","name":"Agent: \u00e9 \u2713 \ud83d\ude00 \"q\"\t\\ \u0001","pid":"4242","tty":"/dev/ttys001","context_percent":12.5,"context_tokens":3.0,"busy":false,"updated_at":"2026-11-04T10:00:00.000Z"}'
ts_tmp=$(rowts write s-golden "$GPATCH"); py_out=$(rowpy s-golden "$GPATCH")
check "the launcher writes a new row byte for byte as the module does: unicode, escapes, an integral float" "True|same" \
  "$(printf '%s\n' "$py_out" | head -1)|$(cmp -s "$RTS/store/sessions/s-golden" "$RPY/store/sessions/s-golden" && echo same || echo differ)"
check "both writers write the row to a temporary file named alike, renamed into place, none left" "ok|ok|0" \
  "$(tmpshape "$ts_tmp" "$RTS/store/sessions/s-golden")|$(tmpshape "$(printf '%s\n' "$py_out" | sed -n 2p)" "$RPY/store/sessions/s-golden")|$({ ls "$RTS/store/sessions"; ls "$RPY/store/sessions"; } | grep -c 'tmp')"
MPATCH='{"name":"Orch: new","context_percent":41,"updated_at":"2026-11-04T10:05:00.000Z"}'
rowts write s-golden "$MPATCH" >/dev/null; py_out=$(rowpy s-golden "$MPATCH")
check "the launcher merges a patch into the row it finds as the module does, every field kept in place" "True|same" \
  "$(printf '%s\n' "$py_out" | head -1)|$(cmp -s "$RTS/store/sessions/s-golden" "$RPY/store/sessions/s-golden" && echo same || echo differ)"
ODD=$(printf 'a/\303\251\360\237\230\200 b')
check "the row's key is the module's for an odd id: each UTF-16 unit outside the safe set is one underscore" \
  "sessions/a_____b|sessions/a_____b" "$(rowts key "$ODD")|$(ROW_ID="$ODD" ipy "import os; print(ia.row_key(os.environ['ROW_ID']))" 2>&1)"
rowts write "$ODD" '{"role":"agent","updated_at":"2026-11-04T10:00:00.000Z"}' >/dev/null
rowpy "$ODD" '{"role":"agent","updated_at":"2026-11-04T10:00:00.000Z"}' >/dev/null
check "a patch with no stamp is stamped with the write's own time, in the module's form" "same|ok|ok" \
  "$(cmp -s "$RTS/store/sessions/a_____b" "$RPY/store/sessions/a_____b" && echo same || echo differ)|$(rowts write s-stamp '{"role":"agent"}' >/dev/null; jq -r .updated_at "$RTS/store/sessions/s-stamp" | grep -qE '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' && echo ok)|$(rowpy s-stamp '{"role":"agent"}' >/dev/null; jq -r .updated_at "$RPY/store/sessions/s-stamp" | grep -qE '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' && echo ok)"
# row_read: the module's row parser, a row without a stamp being no row.
RRD="$WORK/row-read"; mkdir -p "$RRD/store/sessions"
printf '%s\n' '{"role":"agent","name":"Agent: read","updated_at":"2026-11-04T10:00:00.000Z"}' > "$RRD/store/sessions/s-ok"
printf '{"role":"agent","name' > "$RRD/store/sessions/s-torn"
printf '%s\n' '{"role":"agent"}' > "$RRD/store/sessions/s-nostamp"
printf '%s\n' '["not", "a row"]' > "$RRD/store/sessions/s-list"
check "row_read reads a row, and none from an absent, torn, unstamped or non-object file" "Agent: read|None|None|None|None" \
  "$(ORCHESTRATOR_MODULE_DIR="$RRD" ipy "print('|'.join(str(r and r.get('name')) for r in map(ia.row_read, ('s-ok', 's-absent', 's-torn', 's-nostamp', 's-list'))))" 2>&1)"
# The launcher writes a row only before its host starts (a birth) or once it is gone (an end):
# never over a row whose pid runs live, by the module's own rule (runsLive), on the stand-in
# table. A table that cannot be read proves no death.
RREF="$WORK/row-refuse"; mkdir -p "$RREF/store/sessions"
printf '/dev/ttys001 4242 /opt/x/a-host\nttys002 5151 sh\n' > "$WORK/ps-row.txt"
seedrow() { printf '{"role":"agent","name":"Agent: %s","pid":"%s","tty":"%s","updated_at":"2026-11-04T09:00:00.000Z"}\n' "$1" "$2" "$3" > "$RREF/store/sessions/$1"; }
seedrow live 4242 /dev/ttys001; seedrow moved 4242 /dev/ttys009; seedrow dead 7777 /dev/ttys001
rowwrite() { ORCHESTRATOR_MODULE_DIR="$RREF" ORCHESTRATOR_PS_TABLE="${3:-$WORK/ps-row.txt}" ipy "print(ia.row_write('$1', {'name': 'Agent: new'}, '$2'))" 2>&1; }
check "a birth or an end over a row whose pid runs live is refused, the row left as it was" "False|False|Agent: live" \
  "$(rowwrite live birth)|$(rowwrite live end)|$(jq -r .name "$RREF/store/sessions/live")"
check "a row whose pid runs on another tty, or no longer runs, is written over" "True|True|Agent: new|Agent: new" \
